	border-bottom: 1px solid #133f41;
}

#header ul.menu li a {
	color: #fff;
}

#panel input.button {
	background: #1e6365 url(themes/colorize/colors/water_thead.png) top left repeat-x;
}

#topmenu ul li a {
 border-bottom: 4px solid transparent;
color: #fff;
}

#topmenu ul li a:hover {
 border-bottom: 4px solid #ff7500;
 color: #ff7500;
}

#topmenu ul li.selected a {
color: #E6E6E6;
border-bottom: 4px solid #ff7500;
}

#panel .lower ul.user_links li a:hover {
   color: #1e6365;
}

.forum_on {
color: #1e6365;
}

.subforum_minion {
	color: #1e6365;
}

.thead {
	background: #1e6365;
	border-bottom: 1px solid #133f41;
}

.thead input.textbox,
.thead select {
	border: 1px solid #133f41;
}

.popup_menu .popup_item:hover {
	background: #2d9595;
	color: #fff;
}

.tt-suggestion.tt-is-under-cursor {
    background-color: #2d9595;
	color: #fff;
}

.pagination a:hover {
	background-color: #2d9595;
	color: #fff;
	border-color: #133f41;
}

/*
 * MyBB: Colorize Theme 
 *
 * File: usercp.css
 * 
 * Authors: iAndrew & vintagedaddyo
 *
 * MyBB Version: 1.8
 *
 * Theme Version: 1.0
 * 
 */

.usercp_nav_item {
	display: block;
	padding: 1px 0 1px 23px;
	background-image: url(themes/colorize/usercp_sprite.png);
	background-repeat: no-repeat;
}

.usercp_nav_composepm {
	background-position: 0 0;
}

.usercp_nav_pmfolder {
	background-position: 0 -20px;
}

.usercp_nav_sub_pmfolder {
	padding-left: 40px;
	background-position: 0 -40px;
}

.usercp_nav_trash_pmfolder {
	padding-left: 40px;
	background-position: 0 -60px;
}

.usercp_nav_pmtracking {
	background-position: 0 -80px;
}

.usercp_nav_pmfolders {
	background-position: 0 -100px;
}

.usercp_nav_profile {
	background-position: 0 -120px;
}

.usercp_nav_email {
	padding-left: 40px;
	background-position: 0 -140px;
}

.usercp_nav_password {
	padding-left: 40px;
	background-position: 0 -160px;
}

.usercp_nav_username {
	padding-left: 40px;
	background-position: 0 -180px;
}

.usercp_nav_editsig {
	padding-left: 40px;
	background-position: 0 -200px;
}

.usercp_nav_avatar {
	padding-left: 40px;
	background-position: 0 -220px;
}

.usercp_nav_options {
	background-position: 0 -240px;
}

.usercp_nav_usergroups {
	background-position: 0 -260px;
}

.usercp_nav_editlists {
	background-position: 0 -280px;
}

.usercp_nav_attachments {
	background-position: 0 -300px;
}

.usercp_nav_drafts {
	background-position: 0 -320px;
}

.usercp_nav_subscriptions {
	background-position: 0 -340px;
}

.usercp_nav_fsubscriptions {
	background-position: 0 -360px;
}

.usercp_nav_viewprofile {
	background-position: 0 -380px;
}

.usercp_nav_home {
	background-position: 0 -400px;
}

.usercp_notepad {
	width: 99%;
}

.usercp_container {
	margin: 5px;
	padding: 8px;
	border:1px solid #CCCCCC;
}

.pmspace {
	float: right;
	margin: -3px 5px;
}

.pmspace_container {
	background: #fff;
	border: 1px solid #ccc;
	width: 100px;
	display: inline-block;
}

.pmspace_used {
	display: inline-block;
	color: #fff;
	margin: -1px;
}

.pmspace_used.low {
	border: 1px solid #0c5a01;
	background: #167203;
}

.pmspace_used.medium {
	background: #ff862b;
	border: 1px solid #d7611e;
}

.pmspace_used.high {
	background: #e73c3c;
	border: 1px solid #c00;
}

.pmspace_unused {
	display: inline-block;
}

.pmspace_text {
	padding: 1px 5px;
	display: inline-block;
}

.new_pm {
	font-weight: bold;
}

/*
 * MyBB: Colorize Theme 
 *
 * File: modcp.css
 * 
 * Authors: iAndrew & vintagedaddyo
 *
 * MyBB Version: 1.8
 *
 * Theme Version: 1.0
 * 
 */

.modcp_nav_item {
	display: block;
	padding: 1px 0 1px 23px;
	background-image: url('themes/colorize/modcp_sprite.png');
	background-repeat: no-repeat;
}

.modcp_nav_home {
	background-position: 0 0;
}

.modcp_nav_announcements {
	background-position: 0 -20px;
}

.modcp_nav_reports {
	background-position: 0 -40px;
}

.modcp_nav_modqueue {
	background-position: 0 -60px;
}

.modcp_nav_modlogs {
	background-position: 0 -80px;
}

.modcp_nav_editprofile {
	background-position: 0 -100px;
}

.modcp_nav_banning {
	background-position: 0 -120px;
}

.modcp_nav_warninglogs {
	background-position: 0 -140px;
}

.modcp_nav_ipsearch {
	background-position: 0 -160px;
}

.modqueue_message {
	overflow: auto;
	max-height: 250px;
}

.modqueue_controls {
	width: 270px;
	float: right;
	text-align: center;
	border: 1px solid #ccc;
	background: #fff;
	padding: 6px;
	font-weight: bold;
}

.modqueue_controls label {
	margin-right: 8px;
}

.label_radio_ignore,
.label_radio_delete,
.label_radio_approve {
	font-weight: bold;
}

.modqueue_meta {
	color: #444;
	font-size: 95%;
	margin-bottom: 8px;
}

.modqueue_mass {
	list-style: none;
	margin: 0;
	width: 150px;
	padding: 0;
}

.modqueue_mass li {
	margin-bottom: 4px;
	padding: 0;
}

.modqueue_mass li a {
	display: block;
	padding: 4px;
	border: 1px solid transparent;
}

.modqueue_mass li a:hover {
	background: #efefef;
	border: 1px solid #ccc;
	text-decoration: none;
}
